function makeMinuteTimeline(start,end){const a=[],s=toMinutes(start),e=toMinutes(end);for(let n=s;n<=e;n++){a.push(`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`);}return a;}
function buildMetricSeries(session,quiet=false){
  const times=makeMinuteTimeline(session.info.start,session.info.end),at=(t)=>toMinutes(t)-toMinutes(session.info.start);
  const between=(i,a,b)=>i>=at(a)&&i<=at(b),round=(n,d=0)=>Number(n.toFixed(d));
  const values={gmv:[],spend:[],exposure:[],online:[],avgWatch:[],productCtr:[],productCvr:[],interaction:[],followRate:[],negativeRate:[],negativeCount:[],refundRate:[],orders:[]};
  times.forEach((_,i)=>{
    const wave=Math.sin(i/13)*520+Math.sin(i/5)*180,base=quiet?4300:4700;
    let gmv=Math.max(350,base+wave+(i%47===0?3600:0)),spend=quiet?48+Math.sin(i/20)*4:52+Math.sin(i/18)*7;
    if(!quiet&&between(i,'16:32','16:52')){const r=(i-at('16:32'))/20;gmv=4200-r*1500+Math.sin(i)*170;spend=58+r*28;}
    values.gmv.push(round(gmv));values.spend.push(round(spend,1));
    values.exposure.push(round((quiet?820:930)+Math.sin(i/9)*110+(i%31===0?260:0)));
    values.online.push(round((quiet?380:460)+Math.sin(i/17)*55));values.avgWatch.push(round(82+Math.sin(i/21)*9,1));
    let ctr=quiet?13.4+Math.sin(i/16):14.2+Math.sin(i/15)*1.4;if(!quiet&&between(i,'14:05','14:28'))ctr=8.3+Math.sin(i/3)*.35;if(!quiet&&between(i,'15:56','16:18'))ctr=18.7+Math.sin(i/4)*.4;
    let cvr=quiet?4.1+Math.sin(i/19)*.25:4.3+Math.sin(i/18)*.45;if(!quiet&&between(i,'15:56','16:18'))cvr=5.6+Math.sin(i/5)*.25;if(!quiet&&between(i,'17:04','17:40'))cvr=2.1+Math.sin(i/4)*.18;
    values.productCtr.push(round(ctr,2));values.productCvr.push(round(cvr,2));values.interaction.push(round(6.4+Math.sin(i/14)*.7,2));values.followRate.push(round(2.8+Math.sin(i/24)*.35,2));values.negativeRate.push(round(.18+Math.max(0,Math.sin(i/27))*.08,2));values.negativeCount.push(round(1+Math.max(0,Math.sin(i/11))*3));values.refundRate.push(round(!quiet&&between(i,'17:48','18:15')?25:11.8+Math.sin(i/29),2));values.orders.push(round(gmv/900));
  });
  const defs={gmv:['成交金额','元','currency'],spend:['投放消耗','元','currency'],exposure:['曝光人数','人','number'],online:['在线人数','人','number'],avgWatch:['人均观看时长','秒','number'],productCtr:['商品点击率','%','percent'],productCvr:['点击成交率','%','percent'],interaction:['互动率','%','percent'],followRate:['关注率','%','percent'],negativeRate:['负反馈率','%','percent'],negativeCount:['负反馈次数','次','number'],refundRate:['退款率','%','percent'],orders:['成交订单','单','number']};
  session.minuteTimeline=times;session.metricSeries=Object.fromEntries(Object.entries(defs).map(([key,[name,unit,axisFormat]])=>[key,{name,unit,axisFormat,values:values[key]}]));
}
